// App icons (PWA, favicon, desktop) are generated by scripts/make-icons.mjs and committed.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { ASSETS, ICONS } from '../scripts/make-icons.mjs';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const ICON_DIR = path.join(ROOT, 'public', 'icons');
const ASSET_DIR = path.join(ROOT, 'assets');

test('committed icons match the generator', () => {
  for (const [name, make] of Object.entries(ICONS)) {
    const committed = readFileSync(path.join(ICON_DIR, name));
    assert.ok(committed.equals(Buffer.from(make())), `${name} is stale — run: node scripts/make-icons.mjs`);
  }
});

test('PNG icons are valid and have the sizes the manifest declares', () => {
  const sizes = { 'icon-192.png': 192, 'icon-512.png': 512, 'icon-maskable-512.png': 512, 'apple-touch-icon.png': 180 };
  for (const [name, size] of Object.entries(sizes)) {
    const png = readFileSync(path.join(ICON_DIR, name));
    assert.deepEqual([...png.subarray(0, 8)], [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a], `${name} signature`);
    assert.equal(png.toString('ascii', 12, 16), 'IHDR');
    assert.equal(png.readUInt32BE(16), size, `${name} width`);
    assert.equal(png.readUInt32BE(20), size, `${name} height`);
  }
  const manifest = JSON.parse(readFileSync(path.join(ICON_DIR, '..', 'manifest.webmanifest'), 'utf8'));
  for (const icon of manifest.icons) {
    const file = path.basename(icon.src);
    if (sizes[file]) assert.equal(icon.sizes, `${sizes[file]}x${sizes[file]}`, file);
  }
});

test('desktop icon assets match the generator', () => {
  for (const [name, make] of Object.entries(ASSETS)) {
    const committed = readFileSync(path.join(ASSET_DIR, name));
    assert.ok(committed.equals(Buffer.from(make())), `${name} is stale — run: node scripts/make-icons.mjs`);
  }
  const png = readFileSync(path.join(ASSET_DIR, 'icon.png'));
  assert.equal(png.readUInt32BE(16), 512, 'icon.png width');
  assert.equal(png.readUInt32BE(20), 512, 'icon.png height');
});

test('.ico bundles every PNG size Windows asks for', () => {
  const ico = readFileSync(path.join(ASSET_DIR, 'icon.ico'));
  assert.equal(ico.readUInt16LE(0), 0, 'reserved');
  assert.equal(ico.readUInt16LE(2), 1, 'type: icon');
  const count = ico.readUInt16LE(4);
  const sizes = [];
  for (let i = 0; i < count; i++) {
    const at = 6 + i * 16;
    const size = ico[at] || 256; // 0 means 256
    sizes.push(size);
    assert.equal(ico.readUInt16LE(at + 4), 1, `entry ${size} colour planes`);
    assert.equal(ico.readUInt16LE(at + 6), 32, `entry ${size} bits per pixel`);
    const offset = ico.readUInt32LE(at + 12);
    const next = i + 1 < count ? ico.readUInt32LE(6 + (i + 1) * 16 + 12) : ico.length;
    assert.equal(ico.readUInt32LE(at + 8), next - offset, `entry ${size} byte length`);
    assert.equal(ico.toString('ascii', offset + 1, offset + 4), 'PNG', `entry ${size} is a PNG`);
  }
  assert.deepEqual(sizes, [16, 32, 48, 64, 128, 256]);
});
